package com.nuvio.tv.core.server

internal object ArabCinemetaPairingPage {
    val HTML = """
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="referrer" content="no-referrer"><title>NuvioTV | ArabCinemeta</title>
<style>body{font-family:system-ui;background:#101725;color:white;padding:24px}main{max-width:460px;margin:5vh auto;background:#1b2738;padding:25px;border-radius:20px}h1{font-size:24px}a,button{display:block;width:100%;box-sizing:border-box;text-align:center;margin:16px 0;padding:14px;border-radius:10px;background:#3882e8;color:white;border:0;text-decoration:none;font-size:17px}input{box-sizing:border-box;width:100%;padding:15px;border-radius:9px;background:#0d1724;border:1px solid #7d90ac;color:white;font-size:16px;direction:ltr}p{line-height:1.7;color:#dae5f0}#status{min-height:2em}</style></head>
<body><main><h1>إعداد ArabCinemeta على NuvioTV</h1><p>1. افتح موقع ArabCinemeta وأكمل إعدادات الإضافة.</p><a href="https://arabcinemeta.osamayousry.com" target="_blank" rel="noopener noreferrer">فتح موقع ArabCinemeta</a>
<p>2. انسخ رابط الإضافة المنتهي بـ manifest.json والصقه هنا.</p><form id="send"><input id="manifest" type="url" placeholder="https://.../manifest.json" required autocomplete="off"><button id="submit" type="submit">إرسال إلى التلفزيون</button></form><p id="status" role="status"></p><p>التلفزيون راح يطلب منك تأكيد التثبيت. الرابط صالح للإرسال لمدة 5 دقائق. لازم الهاتف والتلفزيون على نفس الشبكة المحلية.</p></main>
<script>(function(){'use strict';const token=location.hash.substring(1);history.replaceState(null,'',location.pathname);const status=document.getElementById('status'),btn=document.getElementById('submit');if(!/^[a-f0-9]{64}$/i.test(token)){btn.disabled=true;status.textContent='رمز الربط غير صالح، امسح رمز التلفزيون مرة ثانية';return;}document.getElementById('send').addEventListener('submit',async function(e){e.preventDefault();const url=document.getElementById('manifest').value.trim();if(!/^https:\/\/.+\/manifest\.json(?:\?.*)?$/i.test(url)){status.textContent='ألصق رابط HTTPS ينتهي بـ manifest.json';return;}btn.disabled=true;status.textContent='جاري الإرسال...';try{const r=await fetch('/api/manifest',{method:'POST',headers:{'Content-Type':'application/json','X-Pairing-Token':token},body:JSON.stringify({manifest:url}),cache:'no-store',credentials:'omit'});const result=await r.json();status.textContent=result.message;if(!r.ok||!result.ok)btn.disabled=false;}catch(_){status.textContent='تعذر الاتصال. تأكد أن الجهازين بنفس الشبكة.';btn.disabled=false;}});})();</script></body></html>
""".trimIndent()
